from fractions import Fraction

def gaussian_elimination(A):
    n = len(A)
    for i in range(n):
        # Find pivot
        max_row = i
        for j in range(i+1, n):
            if abs(A[j][i]) > abs(A[max_row][i]):
                max_row = j
        A[i], A[max_row] = A[max_row], A[i]

        # Eliminate below
        for j in range(i+1, n):
            factor = Fraction(A[j][i], A[i][i])
            for k in range(n):
                A[j][k] -= factor * A[i][k]

    return A

def rank_matrix(A):
    A = [row[:] for row in A]
    gaussian_elimination(A)
    rank = 0
    for row in A:
        if any(row):
            rank += 1
    return rank

def tseitin_formula(literals, clauses):
    n = len(literals)
    new_vars = list(range(2*n))

    tseitin_clauses = []
    for i in range(n):
        tseitin_clauses.append([literals[i], -new_vars[2*i]])
        tseitin_clauses.append([-literals[i], -new_vars[2*i+1]])
        tseitin_clauses.append([new_vars[2*i], new_vars[2*i+1], literals[i]])

    for clause in clauses:
        clause_var = 2*n
        tseitin_clauses.append([clause_var] + [-l for l in clause])
        for literal in clause:
            tseitin_clauses.append([-clause_var, literal])
            tseitin_clauses.append([-literal, clause_var])
            clause_var += 1

    return new_vars, tseitin_clauses

def generate_random_cnf(n):
    literals = [f'x{i+1}' for i in range(n)]
    clauses = []
    for _ in range(2*n):
        clause = random.sample(literals + [-l for l in literals], 3)
        clauses.append(clause)
    return literals, clauses

def dpll_solver(clauses):
    def solve(model):
        if not clauses:
            return model
        unit_clauses = [c[0] for c in clauses if len(c) == 1]
        if unit_clauses:
            literal = unit_clauses[0]
            new_model = model.copy()
            new_model[literal] = True
            if literal.startswith('-'):
                new_model[literal[1:]] = False
            return solve(new_model)

        literals = [c[0] for c in clauses if not c[0].startswith('-')]
        literal = literals[0]
        new_clauses = [[l for l in c if l != literal and not l.startswith('-'+literal)] for c in clauses]
        result = solve({**model, literal: True})
        if result:
            return result
        else:
            new_clauses = [[l for l in c if l != -literal and not l.startswith(literal[1:]) for c in clauses]
            return solve({**model, literal: False})

    model = {f'x{i+1}': None for i in range(n)}
    return solve(model)

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [5, 10, 15, 20, 30, 40]
