                tropical_hessian_rank = rank_matrix([[1 if i == j else 0 for j in range(2*n)] for i in range(2*n)])

                total_instances += 1
                total_size += sat_proof_size
                total_rank += tropical_hessian_rank
                instances_tested += 1

            except (RecursionError, MemoryError):
